def max_flow(edges):
    # Initialize the flow network with zero flow
    flow = {node: 0 for node in set(edge[0] for edge in edges) | set(edge[1] for edge in edges)}

    # Define a function to find the bottleneck capacity of an edge
    def bottleneck_capacity(edge):
        source, target, capacity = edge
        return min(flow[source], capacity - flow[source])

    # Define a function to augment the flow along a path
    def augment_flow(path):
        bottleneck = min(bottleneck_capacity(edge) for edge in path)
        for edge in path:
            source, target, capacity = edge
            flow[source] -= bottleneck
            flow[target] += bottleneck
        return bottleneck

    # Define a function to find the augmenting path
    def find_augmenting_path():
        queue = [(0, None)]
        parent = {node: None for node in flow}

        while queue:
            node, parent_node = queue.pop(0)

            if node not in flow:
                continue

            for neighbor, capacity in edges[node]:
                if flow[neighbor] < capacity and parent_node != neighbor:
                    queue.append((neighbor, node))
                    parent[neighbor] = node

        return parent

    # The main loop of the Ford-Fulkerson algorithm
    while True:
        augmenting_path = find_augmenting_path()

        if augmenting_path is None:
            break

        bottleneck = augment_flow(list(augmenting_path.values()))

    return sum(flow.values())

# Example usage
